const text = $input.item.json.content[0].text;
const items = JSON.parse(text);
return items.map(a => ({ json: a }));

// NO AI CALL IN THIS NODE. Pure validation + date arithmetic, mirrors the
// Risk_Action_Tracker spreadsheet formulas so the workflow and the sheet never disagree.
const plan = $('Read Project_Plan (Owners)').all().map(i => i.json.Owner);
const today = new Date(); today.setHours(0,0,0,0);

return $input.all().map(item => {
  const a = item.json;
  const ownerValid = plan.includes(a.owner) ? 'Valid Owner' : 'NOT FOUND IN PLAN';
  const due = new Date(a.due_date);
  const daysToDue = Math.round((due - today) / 86400000);
  let status = 'ON TRACK';
  if (daysToDue < 0) status = 'OVERDUE';
  else if (daysToDue <= 3) status = 'AT RISK';
  let note = 'On track — no action';
  if (status === 'OVERDUE' && a.priority === 'High') note = 'ESCALATE TO STEERING COMMITTEE';
  else if (status === 'OVERDUE') note = 'Escalate to workstream lead';
  else if (status === 'AT RISK') note = 'Monitor daily';
  return { json: { ...a, owner_valid: ownerValid, days_to_due: daysToDue, status, escalation_note: note } };
});
